//! 21 个 Urban-PLUMBER 站点的土壤剖面点值，从 CoLM 2024 rawdata 抽出。
//!
//! **生成的产物，不要手改。** 重生成：
//! `cargo run -p oracle --bin extract-urban-soil -- <Sitedata> <rawdata> > 本文件`
//!
//! **为什么要它**：城市站点文件 23 个变量全是形态学量，一个土壤剖面量都
//! 没有；而 CoLM 的城市路径缺了它们就只能去开 122 GB 的 `soil/`。
//! 城市算例一次只读一格 —— 把那一格预先抽出来，门槛就从 122 GB 落到几十 KB。
//!
//! **这些值是量出来的，不是假设的**：来源是 CoLM 2024 rawdata 在该站点
//! 经纬度上的格点值。写进 site.nc 时的 `source` 属性要说出这一点。

/// 一个城市站点的土壤剖面。
///
/// 8 层不是 `nl_soil`（那是 10）—— `mkinidata/MOD_SoilParametersReadin.F90`
/// 是 `DO nsl = 1, 8`，栅格每层一个变量也正好 8 个。多写的层 CoLM 不会看。
pub struct UrbanSoil {
    pub site: &'static str,
    pub lon: f64,
    pub lat: f64,
    pub vf_quartz_mineral: [f64; 8],
    pub vf_gravels: [f64; 8],
    pub vf_sand: [f64; 8],
    pub vf_clay: [f64; 8],
    pub vf_om: [f64; 8],
    pub wf_gravels: [f64; 8],
    pub wf_sand: [f64; 8],
    pub wf_clay: [f64; 8],
    pub wf_om: [f64; 8],
    pub om_density: [f64; 8],
    pub bd_all: [f64; 8],
    pub theta_s: [f64; 8],
    pub k_s: [f64; 8],
    pub csol: [f64; 8],
    pub tksatu: [f64; 8],
    pub tksatf: [f64; 8],
    pub tkdry: [f64; 8],
    pub k_solids: [f64; 8],
    pub psi_s: [f64; 8],
    pub lambda: [f64; 8],
    pub theta_r: [f64; 8],
    pub alpha_vgm: [f64; 8],
    pub l_vgm: [f64; 8],
    pub n_vgm: [f64; 8],
    /// USDA 12 类质地，`-1` 表示栅格在这个像元上没有数据。
    /// CoLM 把负值夹到 0 再取 `BVIC_USDA(0) = 1.0`，所以 `-1` 要照写。
    pub texture: i32,
}

